   382→/// Supply 1000 BTC, borrow 100 BTC, utilization rate = 100 / 900, exchange rate = 900 / 1000
   383→#[test]
   384→fun test_reserve_basic_lifecycle_works() {
   385→    let admin = @0xAD;
   386→    let mut scenario_value = sui::test_scenario::begin(admin);
   387→
   388→    let ctx = scenario_value.ctx();
   389→    let mut reserve = new<MainMarket, BTC>(ctx, 1);
   390→
   391→    let amount = 1000;
   392→    let btc = sui::balance::create_for_testing<BTC>(amount).into_coin(ctx);
   393→    let mut ctokens = reserve.mint_ctokens<MainMarket, BTC>(btc).into_coin(ctx);
   394→    reserve.ensure_invariants_hold<MainMarket, BTC>();
   395→
   396→    let mut borrowed_balance = reserve.borrow_amount<MainMarket, BTC>(100);
   397→    reserve.ensure_invariants_hold<MainMarket, BTC>();
   398→
   399→    assert!(borrowed_balance.value() == 100);
   400→    assert!(reserve.cash == 900);
   401→    assert!(reserve.debt.eq(float::from(100)));
   402→    assert!(reserve.cash_reserve.is_zero());
   403→    assert!(reserve.exchange_rate() == math::float::from_quotient(1, 1));
   404→    assert!(reserve.util_rate() == float::from_quotient(1, 10));
   405→
   406→    // no interest accrue at the moment
   407→    std::unit_test::destroy(borrowed_balance.split(1));
   408→    reserve.repay_amount(borrowed_balance.into_coin(ctx));
   409→    reserve.ensure_invariants_hold<MainMarket, BTC>();
   410→
   411→    assert!(reserve.cash == 999);
   412→    assert!(reserve.debt == float::one());
   413→    assert!(reserve.cash_reserve.is_zero());
   414→
   415→    assert!(reserve.exchange_rate() == math::float::from_quotient(1, 1));
   416→    assert!(reserve.util_rate() == float::from_quotient(1, 1000));
   417→
   418→    let remaining = ctokens.split(10, ctx);
   419→    // this is because there isn't as many cash in the pool as part of the cash goes to cash reserve
   420→    std::unit_test::destroy(remaining);
   421→
   422→    let btc = reserve.burn_ctokens<MainMarket, BTC>(ctokens);
   423→    reserve.ensure_invariants_hold<MainMarket, BTC>();
   424→
   425→    assert!(reserve.cash == 9);
   426→    assert!(reserve.debt.eq(float::from(1)));
   427→    assert!(reserve.cash_reserve.is_zero());
   428→
   429→    assert!(btc.value() == 990);
   430→
   431→    sui::balance::destroy_for_testing(btc);
   432→    std::unit_test::destroy(reserve);
   433→    scenario_value.end();
   434→}
